import { useEffect, useId, useRef, useState } from 'react';

import {
  AiConnection,
  AiPreferences,
  AiProviderId,
  aiBaseUrl,
  aiProviders,
  defaultAiConnection,
  loadAiModels,
  saveAiPreferences,
} from 'app/services/EffectsService/aiProviders';

export const AiConnectionSettings = ({
  preferences,
  onChange,
  disabled,
}: {
  preferences: AiPreferences;
  onChange: (value: AiPreferences) => void;
  disabled: boolean;
}) => {
  const connection =
    preferences.connections[preferences.provider] ??
    defaultAiConnection(preferences.provider);
  const [open, setOpen] = useState(!connection.apiKey);
  const [models, setModels] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const request = useRef<AbortController>();
  const id = useId();
  useEffect(
    () => () => {
      request.current?.abort();
      request.current = undefined;
    },
    [],
  );
  const update = (change: Partial<AiConnection>) => {
    onChange({
      ...preferences,
      connections: {
        ...preferences.connections,
        [connection.provider]: { ...connection, ...change },
      },
    });
    setMessage('');
    setError('');
  };

  return (
    <details open={open} onToggle={event => setOpen(event.currentTarget.open)}>
      <summary>
        AI connection ·{' '}
        {aiProviders.find(item => item.id === connection.provider)?.name}
      </summary>
      <fieldset disabled={disabled || loading}>
        <legend>Provider and model</legend>
        <label>
          AI provider
          <select
            value={connection.provider}
            onChange={event => {
              onChange({
                ...preferences,
                provider: event.target.value as AiProviderId,
              });
              setModels([]);
              setMessage('');
              setError('');
            }}
          >
            {aiProviders.map(provider => (
              <option key={provider.id} value={provider.id}>
                {provider.name}
              </option>
            ))}
          </select>
        </label>
        {connection.provider === 'custom' && (
          <label>
            API base URL
            <input
              type="url"
              value={connection.baseUrl}
              maxLength={500}
              placeholder="https://your-provider.example/v1"
              onChange={event => {
                update({ baseUrl: event.target.value });
                setModels([]);
              }}
            />
          </label>
        )}
        <label>
          API key
          <input
            type="password"
            autoComplete="off"
            spellCheck={false}
            value={connection.apiKey}
            aria-describedby={`${id}-key-warning`}
            onChange={event => {
              update({ apiKey: event.target.value });
              setModels([]);
            }}
          />
        </label>
        <p id={`${id}-key-warning`}>
          After saving the connection, your key is stored locally in this
          browser without encryption. Scripts on this page and users of this
          browser profile can access it. Requests go directly to the selected
          provider; its API may charge fees. No audio is sent.
        </p>
        <label>
          AI model
          <input
            value={connection.model}
            maxLength={200}
            list={`${id}-models`}
            placeholder="Text model ID"
            onChange={event => update({ model: event.target.value })}
          />
          <datalist id={`${id}-models`}>
            {models.map(model => (
              <option key={model} value={model} />
            ))}
          </datalist>
        </label>
        <button
          type="button"
          onClick={async () => {
            setLoading(true);
            setError('');
            setMessage('');
            const controller = new AbortController();
            request.current = controller;
            const timeout = window.setTimeout(() => controller.abort(), 20000);
            controller.signal.addEventListener(
              'abort',
              () => window.clearTimeout(timeout),
              { once: true },
            );
            try {
              const next = await loadAiModels(connection, controller.signal);
              if (request.current !== controller) return;
              setModels(next);
              setMessage(
                next.length
                  ? `Available models: ${next.length}. Choose a model above.`
                  : 'No text models found. Enter an ID manually.',
              );
            } catch (reason) {
              if (request.current !== controller) return;
              setError(
                controller.signal.aborted
                  ? 'The model list did not load within 20 seconds. Enter an ID manually.'
                  : reason instanceof TypeError
                  ? "Could not connect. Check your network and the provider's support for browser requests (CORS)."
                  : reason instanceof Error
                  ? reason.message
                  : 'Could not load models.',
              );
            } finally {
              window.clearTimeout(timeout);
              if (request.current === controller) {
                request.current = undefined;
                setLoading(false);
              }
            }
          }}
        >
          {loading ? 'Loading models…' : 'Load models'}
        </button>{' '}
        <button
          type="button"
          onClick={() => {
            setError('');
            try {
              aiBaseUrl(connection);
            } catch (reason) {
              setError((reason as Error).message);
              return;
            }
            const saved = saveAiPreferences({
              ...preferences,
              connections: {
                ...preferences.connections,
                [connection.provider]: connection,
              },
            });
            if (saved) setMessage('Connection saved locally in this browser.');
            else {
              setMessage('');
              setError(
                'Your browser blocked saving. The key is available only until you close this panel.',
              );
            }
          }}
        >
          Save connection
        </button>{' '}
        <button
          type="button"
          disabled={!connection.apiKey}
          onClick={() => {
            const next = {
              ...preferences,
              connections: {
                ...preferences.connections,
                [connection.provider]: { ...connection, apiKey: '' },
              },
            };
            onChange(next);
            setModels([]);
            if (saveAiPreferences(next)) {
              setError('');
              setMessage(
                "This provider's key has been removed from the browser.",
              );
            } else {
              setMessage('');
              setError(
                'Could not remove the saved key. Clear site data in your browser settings.',
              );
            }
          }}
        >
          Delete key
        </button>
        {connection.provider === 'openrouter' && (
          <p>
            OpenRouter offers Claude, GPT, Gemini, DeepSeek and other text
            models.
          </p>
        )}
        <p>
          Load the current model list or enter an ID manually. Direct requests
          depend on the provider and its CORS policy.
        </p>
      </fieldset>
      {message && <p role="status">{message}</p>}
      {error && <p role="alert">{error}</p>}
    </details>
  );
};
