import { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import styled from 'styled-components';

import {
  Tuning,
  centsBetween,
  nearestNote,
  nearestString,
  noteFrequency,
  tunings,
} from 'app/services/TunerService/pitch';
import { useTuner } from 'app/services/TunerService/useTuner';

import { HeaderIcon } from 'app/components/HeaderIcon';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

const formatCents = (cents: number) => {
  const value = Math.round(cents);
  const absolute = Math.abs(value);
  const ending = absolute === 1 ? 'cent' : 'cents';
  return `${value > 0 ? '+' : ''}${value} ${ending}`;
};

export const TunerPage = () => {
  const tuner = useTuner();
  const [tuning, setTuning] = useState<Tuning>('standard');
  const [selected, setSelected] = useState<number | null>(null);
  const listening = tuner.status === 'listening';
  const frequency = tuner.frequency;
  const active =
    selected ?? (frequency ? nearestString(frequency, tuning) : null);
  const target = active === null ? null : tunings[tuning].notes[active];
  const cents =
    frequency && target ? centsBetween(frequency, noteFrequency(target)) : null;
  const inTune = cents !== null && Math.abs(cents) <= 5;
  const position =
    cents === null ? 50 : 50 + Math.max(-50, Math.min(50, cents));
  const message = !listening
    ? 'Ready to tune'
    : cents === null
    ? 'Play one open string'
    : inTune
    ? 'String in tune'
    : cents < 0
    ? 'Tighten the string'
    : 'Loosen the string';

  return (
    <PageWrapper aria-label="Guitar tuner">
      <Helmet>
        <title>Guitar tuner</title>
      </Helmet>
      <Layout>
        <Heading>
          <Eyebrow>
            <HeaderIcon name="tuner" /> GUITAR TUNER
          </Eyebrow>
          <h1>Every string in tune</h1>
          <p>Tune a six-string guitar with a microphone or audio interface.</p>
        </Heading>
        <InputPanel aria-label="Tuner audio input">
          <InputFields>
            <Field>
              Audio input
              <select
                value={tuner.deviceId}
                disabled={!tuner.supported || tuner.status === 'connecting'}
                onChange={event => tuner.selectDevice(event.target.value)}
              >
                <option value="">Default microphone</option>
                {tuner.deviceId &&
                  !tuner.devices.some(
                    device => device.deviceId === tuner.deviceId,
                  ) && (
                    <option value={tuner.deviceId}>Selected audio input</option>
                  )}
                {tuner.devices
                  .filter(device => device.deviceId)
                  .map((device, index) => (
                    <option key={device.deviceId} value={device.deviceId}>
                      {device.label || `Audio input ${index + 1}`}
                    </option>
                  ))}
              </select>
            </Field>
            {listening && tuner.channels > 1 && (
              <Field>
                Channel
                <select
                  value={tuner.channel}
                  onChange={event =>
                    tuner.selectChannel(Number(event.target.value))
                  }
                >
                  {Array.from({ length: tuner.channels }, (_, index) => (
                    <option key={index} value={index}>
                      Input {index + 1}
                    </option>
                  ))}
                </select>
              </Field>
            )}
            <Start
              type="button"
              disabled={!tuner.supported}
              onClick={() =>
                tuner.status === 'idle' ? void tuner.start() : tuner.stop()
              }
            >
              {tuner.status === 'connecting'
                ? 'Cancel connection'
                : listening
                ? 'Turn off tuner'
                : 'Turn on microphone'}
            </Start>
          </InputFields>
          <LevelRow>
            <span>{listening ? 'Input level' : 'Microphone is off'}</span>
            <progress
              aria-label="Audio input level"
              max={1}
              value={tuner.level}
            />
          </LevelRow>
          {tuner.clipping && (
            <Warning role="status">Clipping. Reduce audio input gain.</Warning>
          )}
          {tuner.error && (
            <ErrorMessage role="alert">{tuner.error}</ErrorMessage>
          )}
          {!tuner.supported && (
            <ErrorMessage role="alert">
              The tuner requires a browser with microphone access and Web Audio.
              Open the app over HTTPS or localhost.
            </ErrorMessage>
          )}
          <Privacy>
            Audio is analyzed on your device, without recording or uploading.
          </Privacy>
        </InputPanel>
        <Panel>
          <Settings>
            <Field>
              Guitar tuning
              <select
                value={tuning}
                onChange={event => setTuning(event.target.value as Tuning)}
              >
                {Object.entries(tunings).map(([id, value]) => (
                  <option key={id} value={id}>
                    {value.label}
                  </option>
                ))}
              </select>
            </Field>
            <Mode>
              <span>String selection</span>
              <ModeButtons aria-label="String selection">
                <button
                  type="button"
                  aria-pressed={selected === null}
                  onClick={() => setSelected(null)}
                >
                  Auto
                </button>
                <button
                  type="button"
                  aria-pressed={selected !== null}
                  onClick={() => setSelected(active ?? 0)}
                >
                  Manual
                </button>
              </ModeButtons>
            </Mode>
            <Reference>
              Reference <strong>A4 = 440 Hz</strong>
            </Reference>
          </Settings>

          <Display $inTune={inTune}>
            <NoteLabel>
              {target
                ? `String ${6 - active!} · target ${target}`
                : listening
                ? 'Listening for an open string'
                : `${tunings[tuning].label} · 6 strings`}
            </NoteLabel>
            <Note aria-label="Detected note">
              {frequency
                ? nearestNote(frequency).slice(0, -1)
                : target?.slice(0, -1) ?? '—'}
              <small>
                {frequency
                  ? nearestNote(frequency).slice(-1)
                  : target?.slice(-1)}
              </small>
            </Note>
            <Frequency>
              {frequency
                ? `${frequency.toFixed(1)} Hz`
                : 'Frequency will appear here'}
            </Frequency>
            <Gauge
              role="meter"
              aria-label="Pitch deviation"
              aria-valuemin={-50}
              aria-valuemax={50}
              aria-valuenow={
                cents === null
                  ? 0
                  : Math.max(-50, Math.min(50, Math.round(cents)))
              }
              aria-valuetext={
                cents === null
                  ? 'No signal'
                  : `${formatCents(cents)}. ${message}`
              }
            >
              <Ticks aria-hidden="true">
                {Array.from({ length: 21 }, (_, index) => (
                  <i key={index} />
                ))}
              </Ticks>
              <Center aria-hidden="true" />
              {cents !== null && (
                <Needle aria-hidden="true" style={{ left: `${position}%` }} />
              )}
            </Gauge>
            <Scale aria-hidden="true">
              <span>−50</span>
              <span>0</span>
              <span>+50</span>
            </Scale>
            <Feedback role="status" aria-live="polite">
              {message}
            </Feedback>
            <Cents>
              {cents === null
                ? 'Deviation in cents'
                : `${formatCents(cents)}${inTune ? ' · in tune' : ''}`}
            </Cents>
          </Display>

          <Strings aria-label="Guitar strings">
            {tunings[tuning].notes.map((note, index) => (
              <StringButton
                key={index}
                type="button"
                aria-label={`String ${6 - index} ${note}`}
                aria-pressed={active === index}
                $inTune={active === index && inTune}
                onClick={() => setSelected(index)}
              >
                <span>{6 - index}</span>
                <strong>
                  {note.slice(0, -1)}
                  <small>{note.slice(-1)}</small>
                </strong>
                <span>
                  {noteFrequency(note).toFixed(1)}
                  <span className="unit"> Hz</span>
                </span>
              </StringButton>
            ))}
          </Strings>
          <StringHint>
            From thickest to thinnest. Click a string to tune it manually.
          </StringHint>
        </Panel>

        <Help>
          <h2>How to tune your guitar</h2>
          <ol>
            <li>Turn on the microphone and allow access in your browser.</li>
            <li>
              Play an open string and mute the others. In Auto mode, the tuner
              selects the nearest string.
            </li>
            <li>
              Turn the tuning peg until the pointer is centered. For a very
              out-of-tune guitar, select the string manually.
            </li>
          </ol>
          <p>
            Tune in a quiet place. Stop the metronome, drum machine and playback
            so the tuner hears only your guitar.
          </p>
        </Help>
      </Layout>
    </PageWrapper>
  );
};

