import { melodies } from './melodies/melodies';

export const RECENT_MELODIES_KEY = 'qwertophone.recentMelodies.v1';

export const readRecentMelodies = (): string[] => {
  try {
    const saved: unknown = JSON.parse(
      localStorage.getItem(RECENT_MELODIES_KEY) ?? '[]',
    );
    if (!Array.isArray(saved)) return [];
    const titles = new Set(melodies.map(melody => melody.title));
    return Array.from(
      new Set(
        saved.filter(
          (title): title is string =>
            typeof title === 'string' && titles.has(title),
        ),
      ),
    );
  } catch {
    return [];
  }
};

export const saveRecentMelodies = (titles: string[]) => {
  try {
    localStorage.setItem(RECENT_MELODIES_KEY, JSON.stringify(titles));
  } catch {
    // Keep the order in Redux for this session if storage is unavailable.
  }
};
