import { getNoteDuration } from 'app/services/MelodiesService/timing';
import type { Melody } from 'app/services/MelodiesService/types';

import type {
  NotesState,
  RecordingProject,
  RecordingTrack,
} from './slice/types';

export const getRecordingContext = (
  project?: Pick<RecordingProject, 'id' | 'activeTrackId'>,
) =>
  project ? `recording:${project.id}:${project.activeTrackId}` : 'recording';

export const recordingMelody = (melody: Melody): Melody => ({
  ...melody,
  firstStart: undefined,
  notes: melody.notes.map(note => ({
    ...note,
    duration: getNoteDuration(note),
  })),
});

export const recordingProject = (
  state: Pick<
    NotesState,
    'melody' | 'project' | 'melodyBeforeNormalization' | 'recordingVersion'
  >,
): RecordingProject => {
  const project = state.project ?? {
    id: state.recordingVersion,
    title: state.melody.title || 'New composition',
    activeTrackId: 'track-1',
    tracks: [{ id: 'track-1', name: 'Track 1', melody: state.melody }],
  };
  return {
    ...project,
    tracks: project.tracks.map(track =>
      track.id === project.activeTrackId
        ? {
            ...track,
            melody: state.melody,
            melodyBeforeNormalization: state.melodyBeforeNormalization,
          }
        : track,
    ),
  };
};

export const saveActiveTrack = (state: NotesState, current?: Melody) => {
  state.project = recordingProject(state);
  const active = state.project.tracks.find(
    track => track.id === state.project!.activeTrackId,
  )!;
  active.melody = current ?? state.melody;
  active.melodyBeforeNormalization = state.melodyBeforeNormalization;
};

export const activateTrack = (state: NotesState, track: RecordingTrack) => {
  state.project!.activeTrackId = track.id;
  state.recordingVersion++;
  state.liveGuitarNotes = undefined;
  state.liveAudioNotes = [];
  state.melody = recordingMelody(track.melody);
  state.melodyBeforeNormalization = track.melodyBeforeNormalization;
};
