import { useSelector } from 'react-redux';
import styled from 'styled-components';

import { chordSymbol, detectChords } from 'app/services/ChordsService';
import { expressionLabel } from 'app/services/MelodiesService/expression';
import type { NoteInMelody } from 'app/services/MelodiesService/types';
import { selectNotes } from 'app/services/NotesService';
import { selectSettings } from 'app/services/SettingsService';

export const LiveAudioRecognition = () => {
  const {
    liveAudioNotes = [],
    liveGuitarNotes = {},
    melody,
  } = useSelector(selectNotes);
  const { isRecording } = useSelector(selectSettings);
  if (!isRecording || !liveAudioNotes.length) return null;
  const chords = detectChords(liveAudioNotes).map(chordSymbol);
  const latest = new Map<string, NoteInMelody>();
  Object.values(liveGuitarNotes).forEach(index => {
    const note = melody.notes[index];
    if (
      note &&
      liveAudioNotes.includes(note.note) &&
      (!latest.has(note.note) || latest.get(note.note)!.start <= note.start)
    )
      latest.set(note.note, note);
  });
  const techniques = Array.from(
    new Set(
      Array.from(latest.values())
        .map(note => expressionLabel(note.expression))
        .filter(Boolean),
    ),
  );
  return (
    <Recognition
      role="status"
      aria-label="Audio input recognition"
      aria-live="off"
    >
      <span>Notes: {liveAudioNotes.join(' · ')}</span>
      {!!chords.length && <strong>Chord: {chords.join(' / ')}</strong>}
      {!!techniques.length && (
        <strong>Techniques: {techniques.join(' · ')}</strong>
      )}
    </Recognition>
  );
};

const Recognition = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 12px;
  margin: 8px 0;
  font-size: 12px;
  line-height: 1.6;
  color: ${p => p.theme.text};
  strong {
    color: ${p => p.theme.primary};
  }
`;
