import { MAX_SAMPLE_SECONDS } from './samples';

export const createSampleRecording = ({
  onReady,
  onComplete,
  onError,
}: {
  onReady: () => void;
  onComplete: (blob: Blob) => void;
  onError: (error: Error) => void;
}) => {
  let stream: MediaStream | undefined;
  let recorder: MediaRecorder | undefined;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let cancelled = false;
  const chunks: Blob[] = [];
  const release = () => {
    clearTimeout(timer);
    stream?.getTracks().forEach(track => track.stop());
  };
  const stop = () => {
    if (recorder?.state === 'recording') recorder.stop();
    release();
  };

  return {
    async start() {
      try {
        if (
          !navigator.mediaDevices?.getUserMedia ||
          typeof MediaRecorder === 'undefined'
        ) {
          throw new Error(
            'Microphone recording is unavailable. Open the app over HTTPS or upload an audio file.',
          );
        }
        stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        if (cancelled) {
          release();
          return;
        }
        recorder = new MediaRecorder(stream);
        recorder.ondataavailable = event => {
          if (event.data.size) chunks.push(event.data);
        };
        recorder.onstop = () => {
          release();
          if (cancelled) return;
          const blob = new Blob(chunks, { type: recorder!.mimeType });
          if (blob.size) onComplete(blob);
          else
            onError(new Error('The microphone captured no sound. Try again.'));
        };
        recorder.onerror = () => {
          cancelled = true;
          stop();
          onError(new Error('Could not record the microphone. Try again.'));
        };
        recorder.start();
        timer = setTimeout(stop, MAX_SAMPLE_SECONDS * 1000);
        onReady();
      } catch (error) {
        release();
        if (!cancelled) {
          onError(
            new Error(
              error instanceof DOMException && error.name === 'NotAllowedError'
                ? 'No microphone access. Allow it in your browser or upload an audio file.'
                : error instanceof Error
                ? error.message
                : 'Could not open the microphone.',
            ),
          );
        }
      }
    },
    stop,
    cancel() {
      cancelled = true;
      stop();
    },
  };
};
