import {
  prepareDrumKit,
  prepareInstrumentSample,
} from 'app/services/SynthesizerService';
import { PercussionTimbre } from 'app/services/SynthesizerService/percussion';
import { drumSlot } from 'app/services/SynthesizerService/sampleLayout';
import { sampleDefinition } from 'app/services/SynthesizerService/timbres';

import { DrumMachineState, DrumTrack, defaultDrumState } from './patterns';
import {
  DRUM_ONE_SHOTS,
  MAX_SAMPLE_SECONDS,
  readCustomSample,
  sampleKey,
} from './samples';
import { DrumOutput } from './transport';

export const createDrumOutput = async (): Promise<DrumOutput> => {
  const { audio, buffer, destination } = await prepareDrumKit();
  const master = audio.createGain();
  master.connect(destination);
  const tracks = new Map<DrumTrack, GainNode>();
  const voices = new Map<
    AudioBufferSourceNode,
    { envelope: GainNode; track: DrumTrack }
  >();
  const sampleBuffers = new Map<string, AudioBuffer>();
  const instrumentBuffers = new Map<PercussionTimbre, AudioBuffer>();
  let samples = defaultDrumState().samples;
  const stop = () => {
    voices.forEach(({ envelope }, source) => {
      source.stop();
      source.disconnect();
      envelope.disconnect();
    });
    voices.clear();
  };

  return {
    async loadSample(sample, blob) {
      if (sample.kind === 'instrument') {
        if (!instrumentBuffers.has(sample.timbre)) {
          instrumentBuffers.set(
            sample.timbre,
            await prepareInstrumentSample(sample.timbre),
          );
        }
        return;
      }
      const key = sampleKey(sample);
      if (sampleBuffers.has(key)) return;
      let data: Blob;
      if (sample.kind === 'oneshot') {
        const response = await fetch(
          `${process.env.PUBLIC_URL || ''}/samples/library/${
            DRUM_ONE_SHOTS[sample.id].file
          }`,
        );
        if (!response.ok) {
          throw new Error('Could not load the sample. Try again.');
        }
        data = await response.blob();
      } else {
        data = blob ?? (await readCustomSample(sample.id));
      }
      let decoded: AudioBuffer;
      try {
        decoded = await audio.decodeAudioData(await data.arrayBuffer());
      } catch {
        throw new Error(
          'Could not read audio. Choose a supported WAV, MP3, OGG, M4A or WebM file.',
        );
      }
      if (!decoded.length || decoded.duration > MAX_SAMPLE_SECONDS) {
        throw new Error(
          `The sample must contain audio and be no longer than ${MAX_SAMPLE_SECONDS} seconds.`,
        );
      }
      sampleBuffers.set(key, decoded);
    },
    now: () => audio.currentTime,
    update(state: DrumMachineState) {
      samples = state.samples;
      master.gain.setTargetAtTime(state.volume, audio.currentTime, 0.005);
      tracks.forEach((gain, id) => {
        if (state.tracks.includes(id)) return;
        voices.forEach(({ envelope, track }, source) => {
          if (track !== id) return;
          source.stop();
          source.disconnect();
          envelope.disconnect();
          voices.delete(source);
        });
        gain.disconnect();
        tracks.delete(id);
      });
      state.tracks.forEach(id => {
        let gain = tracks.get(id);
        if (!gain) {
          gain = audio.createGain();
          gain.connect(master);
          tracks.set(id, gain);
        }
        gain.gain.setTargetAtTime(
          state.muted[id] ? 0 : 1,
          audio.currentTime,
          0.005,
        );
      });
    },
    hit(track, when, { preview = false } = {}) {
      const sample = samples[track];
      const gain = tracks.get(track);
      if (!sample || !gain) return;
      const sound =
        sample.kind === 'builtin'
          ? buffer
          : sample.kind === 'instrument'
          ? instrumentBuffers.get(sample.timbre)
          : sampleBuffers.get(sampleKey(sample));
      if (!sound) return;
      const slot =
        sample.kind === 'builtin'
          ? drumSlot(sample.note, sound.duration)
          : sample.kind === 'instrument'
          ? sampleDefinition(sample.timbre).articulations?.[sample.articulation]
          : { offset: 0, duration: sound.duration };
      if (!slot || slot.offset + slot.duration > sound.duration) return;
      const { offset, duration } = slot;
      const source = audio.createBufferSource();
      const envelope = audio.createGain();
      source.buffer = sound;
      source.connect(envelope);
      envelope.connect(preview ? master : gain);
      envelope.gain.setValueAtTime(1, when);
      envelope.gain.setValueAtTime(1, when + Math.max(0, duration - 0.01));
      envelope.gain.linearRampToValueAtTime(0, when + duration);
      voices.set(source, { envelope, track });
      source.onended = () => {
        source.disconnect();
        envelope.disconnect();
        voices.delete(source);
      };
      source.start(when, offset, duration);
    },
    stop,
    dispose() {
      stop();
      tracks.forEach(gain => gain.disconnect());
      tracks.clear();
      master.disconnect();
      sampleBuffers.clear();
      instrumentBuffers.clear();
    },
  };
};
