import { NoiseGateSettings } from './noiseGateSettings';

export const createNoiseGate = (
  audio: BaseAudioContext,
  settings: NoiseGateSettings,
) => {
  const node = new AudioWorkletNode(audio, 'qwertophone-noise-gate', {
    numberOfInputs: 1,
    numberOfOutputs: 1,
    channelCount: 1,
    channelCountMode: 'explicit',
    outputChannelCount: [1],
  });
  const update = (value: NoiseGateSettings) => {
    node.parameters
      .get('enabled')!
      .setValueAtTime(Number(value.enabled), audio.currentTime);
    node.parameters
      .get('threshold')!
      .setValueAtTime(value.threshold, audio.currentTime);
    node.parameters
      .get('release')!
      .setValueAtTime(value.release, audio.currentTime);
  };
  update(settings);
  return {
    node,
    update,
    dispose() {
      node.disconnect();
      node.port.postMessage({ dispose: true });
      node.port.close();
    },
  };
};
