export type HarmonyLessonId = typeof harmonyLessons[number]['id'];
export type LessonExample = { title: string; context: Chord; chords: Chord[] };

export const lessonSource = (lesson: typeof harmonyLessons[number]) =>
  `https://www.youtube.com/watch?v=${lesson.videoId}&t=${lesson.seconds}s`;

export const lessonExamples = (
  id: HarmonyLessonId,
  tonic: string,
  mode: KeyMode,
): LessonExample[] => {
  const major = mode === 'major' ? tonic : spellPitch(tonic, 3, 2);
  const from = (
    semitones: number,
    letters: number,
    quality: ChordQuality = 'major',
  ): Chord => ({ root: spellPitch(major, semitones, letters), quality });
  const C = from(0, 0),
    F = from(5, 3),
    G = from(7, 4),
    Am = from(9, 5, 'minor');
  const Dm = from(2, 1, 'minor'),
    Em = from(4, 2, 'minor'),
    Fm = from(5, 3, 'minor');
  const D7 = from(2, 1, 'dominant7'),
    G7 = from(7, 4, 'dominant7'),
    E7 = from(4, 2, 'dominant7');
  const example = (
    title: string,
    chords: Chord[],
    context = C,
  ): LessonExample => ({ title, chords, context });
  switch (id) {
    case 'orientation':
      return [
        example('Diatonic progression', [C, F, G, C]),
        example('Color from a neighboring key', [C, from(10, 6), F, C]),
      ];
    case 'parallel':
      return [
        example('Major subdominant', [C, F, C]),
        example('Minor subdominant', [C, F, Fm, C]),
      ];
    case 'context':
      return [
        example('Borrowing in major', [C, Fm, C]),
        example('The same chord in relative minor', [Am, Fm, Am], Am),
      ];
    case 'modulation':
      return [
        example('Color and return', [Am, from(6, 3, 'minor'), Am], Am),
        example(
          'Continuation to a new center',
          [Am, from(6, 3, 'minor'), G, from(9, 5), from(2, 1)],
          Am,
        ),
      ];
    case 'melody':
      return [
        example('Expected arrival', [C, E7, Am]),
        example('Delayed resolution', [C, E7, F, Fm, C]),
      ];
    case 'common':
      return [
        example('Connecting triads', [C, from(1, 0, 'minor'), C]),
        example('Two shared notes', [
          from(0, 0, 'major7'),
          from(1, 0, 'minor7'),
          from(0, 0, 'major7'),
        ]),
        example('Tritone substitution before the tonic', [
          Dm,
          from(1, 1, 'dominant7'),
          C,
        ]),
      ];
    case 'secondary':
      return [
        example('Original progression', [C, Dm, G7, C]),
        example('Dominant of the dominant', [C, D7, G7, C]),
        example('Secondary dominant of degree II', [
          C,
          from(9, 5, 'dominant7'),
          Dm,
          G7,
          C,
        ]),
      ];
    case 'steps':
      return [
        example('Fourths and relative chords', [C, F, Dm, Am, C]),
        example('Repeating mediant step', [
          C,
          Em,
          G,
          from(11, 6, 'minor'),
          from(2, 1),
          C,
        ]),
      ];
  }
};
