import { NoteInMelody } from 'app/services/MelodiesService/types';
import { Note } from 'app/services/NotesService/types';

export const CHORD_WINDOW_MS = 50;

export const getStaffStep = (note: Note) =>
  Number(note.slice(-1)) * 7 + 'CDEFGAB'.indexOf(note[0]);

// Rhythm symbols are a reading aid; precise milliseconds stay in the recording.
export const getRhythm = (duration: number | undefined, bpm: number) => {
  if (duration === undefined || duration <= 0) {
    return { beats: 0, hollow: false, stem: true, flags: 0, dotted: false };
  }
  const beats = (duration * bpm) / 60000;
  const values = [0.125, 0.1875, 0.25, 0.375, 0.5, 0.75, 1, 1.5, 2, 3, 4, 6];
  const closest = values.reduce((best, value) =>
    Math.abs(Math.log(beats / value)) < Math.abs(Math.log(beats / best))
      ? value
      : best,
  );
  return {
    beats: closest,
    hollow: closest >= 2,
    stem: closest < 4,
    flags: closest < 0.25 ? 3 : closest < 0.5 ? 2 : closest < 1 ? 1 : 0,
    dotted: [0.1875, 0.375, 0.75, 1.5, 3, 6].includes(closest),
  };
};

export type StaffEvent = NoteInMelody & {
  index: number;
  headOffset: number;
  accidentalColumn: number;
  accidental?: '♯' | '♮';
};
export type StaffChord = { start: number; notes: StaffEvent[] };

export const groupStaffNotes = (
  notes: NoteInMelody[],
  measureDuration = Infinity,
): StaffChord[] => {
  const groups: StaffChord[] = [];
  notes
    .map((note, index) => ({ ...note, index }))
    .sort((a, b) => a.start - b.start)
    .forEach(note => {
      const previous = groups[groups.length - 1];
      if (
        previous &&
        note.start - previous.start < CHORD_WINDOW_MS &&
        Math.floor(note.start / measureDuration) ===
          Math.floor(previous.start / measureDuration) &&
        previous.notes.every(
          n =>
            n.note !== note.note &&
            (n.duration === undefined || n.start + n.duration > note.start),
        )
      ) {
        previous.notes.push({ ...note, headOffset: 0, accidentalColumn: 0 });
      } else {
        groups.push({
          start: note.start,
          notes: [{ ...note, headOffset: 0, accidentalColumn: 0 }],
        });
      }
    });
  groups.forEach(group => {
    group.notes.sort((a, b) => getStaffStep(a.note) - getStaffStep(b.note));
    let previous: StaffEvent | undefined;
    const accidentalSteps: number[] = [];
    group.notes.forEach(note => {
      const step = getStaffStep(note.note);
      if (previous && step - getStaffStep(previous.note) <= 1) {
        // Seconds and chromatic unisons need separate visible noteheads.
        note.headOffset = previous.headOffset === 0 ? 12 : 0;
      }
      if (
        note.note.includes('#') ||
        group.notes.some(
          n => n.note.includes('#') && getStaffStep(n.note) === step,
        )
      ) {
        note.accidental = note.note.includes('#') ? '♯' : '♮';
        let column = accidentalSteps.findIndex(
          lastStep => step - lastStep >= 6,
        );
        if (column === -1) {
          column = accidentalSteps.length;
        }
        accidentalSteps[column] = step;
        note.accidentalColumn = column;
      }
      previous = note;
    });
  });
  return groups;
};
