import { createPortal } from 'react-dom';
import styled from 'styled-components';

import type { RecordingMode } from 'app/services/GuitarInputService/liveTranscription';
import { useGuitarInput } from 'app/services/GuitarInputService/useGuitarInput';

import { GuitarRecordingExport } from './GuitarRecordingExport';
import { InputSoundControls } from './InputSoundControls';
import { LiveAudioRecognition } from './LiveAudioRecognition';
import { LiveInputEffects } from './LiveInputEffects';
import { NoiseGateControls } from './NoiseGateControls';

export const GuitarInput = ({
  open,
  guitar,
}: {
  open: boolean;
  guitar: ReturnType<typeof useGuitarInput>;
}) => {
  const db = Math.max(
    -60,
    Math.round(20 * Math.log10(guitar.level.rms || 0.001)),
  );
  return (
    <Wrapper>
      {guitar.monitoring &&
        createPortal(
          <EmergencyMute
            type="button"
            onClick={guitar.stopMonitoring}
            aria-label="Mute live sound immediately"
          >
            Mute
          </EmergencyMute>,
          document.body,
        )}
      {open && (
        <Panel aria-label="Microphone and guitar">
          <p>
            Choose a microphone or audio interface input and allow access.
            Connect a guitar through a Hi-Z instrument input.
          </p>
          <p>
            The connection and live sound setting are remembered and restored
            after reload. Sound turns on automatically on the first connection.
            If your browser requires permission or a click, allow access and
            reconnect. A microphone near speakers may cause feedback.
          </p>
          {guitar.connecting && <p role="status">{guitar.connectionStatus}</p>}
          <InputSoundControls guitar={guitar} />
          {(guitar.inputSound ?? 'effects') === 'effects' && (
            <NoiseGateControls
              settings={guitar.noiseGate}
              onChange={guitar.updateNoiseGate}
            />
          )}
          {!guitar.supported ? (
            <p role="status">
              Audio capture is unavailable. Open Melody Generator over HTTPS or
              localhost in a browser with Web Audio and AudioWorklet.
            </p>
          ) : guitar.connected ? (
            <>
              <Fields>
                <label>
                  Audio device
                  <select
                    aria-label="Audio input device"
                    value={guitar.deviceId}
                    disabled={guitar.isRecording}
                    onChange={event => guitar.selectDevice(event.target.value)}
                  >
                    {!guitar.devices.some(
                      device => device.deviceId === guitar.deviceId,
                    ) && (
                      <option value={guitar.deviceId}>
                        Current audio input
                      </option>
                    )}
                    {guitar.devices.map((device, index) => (
                      <option key={device.deviceId} value={device.deviceId}>
                        {device.label || `Audio input ${index + 1}`}
                      </option>
                    ))}
                  </select>
                </label>
                <label>
                  Audio interface channel
                  <select
                    aria-label="Audio input channel"
                    value={guitar.channel}
                    disabled={guitar.isRecording}
                    onChange={event =>
                      guitar.selectChannel(Number(event.target.value))
                    }
                  >
                    {Array.from({ length: guitar.channels }, (_, channel) => (
                      <option key={channel} value={channel}>
                        Input {channel + 1}
                      </option>
                    ))}
                  </select>
                </label>
              </Fields>
              {guitar.canSelectOutput ? (
                <label>
                  Audio output
                  <select
                    aria-label="Live sound output"
                    value={guitar.outputDeviceId}
                    onChange={event => guitar.selectOutput(event.target.value)}
                  >
                    <option value="">System output</option>
                    {guitar.outputs
                      .filter(output => output.deviceId !== 'default')
                      .map((output, index) => (
                        <option key={output.deviceId} value={output.deviceId}>
                          {output.label || `Output ${index + 1}`}
                        </option>
                      ))}
                  </select>
                </label>
              ) : (
                <p>Select audio output in your system or browser settings.</p>
              )}
              <Level>
                <span>Input level: {db} dBFS</span>
                <meter
                  min={-60}
                  max={0}
                  value={db}
                  aria-label="Audio input level"
                />
                {guitar.level.peak >= 0.98 ? (
                  <span role="status">
                    Clipping. Reduce your audio interface gain.
                  </span>
                ) : (
                  <span>
                    If there is no signal, check the channel and gain.
                  </span>
                )}
              </Level>
              <Actions>
                {guitar.monitoring ? (
                  <Mute type="button" onClick={guitar.stopMonitoring}>
                    Turn off live sound
                  </Mute>
                ) : (
                  <button type="button" onClick={guitar.startMonitoring}>
                    Turn on live sound
                  </button>
                )}
                <span role="status">
                  {guitar.monitoring ? 'Sound is on' : 'Sound output is off'}
                </span>
              </Actions>
              {guitar.monitoring && (
                <Level>
                  <span>Output level</span>
                  <meter
                    aria-label="Live output level"
                    min={-60}
                    max={0}
                    value={Math.max(
                      -60,
                      20 * Math.log10(guitar.outputLevel.rms || 0.001),
                    )}
                  />
                  {guitar.outputLevel.peak >= 0.98 && (
                    <span role="status">
                      Output clipping. Reduce volume or drive.
                    </span>
                  )}
                </Level>
              )}
              {(guitar.inputSound ?? 'effects') === 'effects' && (
                <LiveInputEffects
                  settings={guitar.liveEffects}
                  onChange={guitar.updateLiveEffects}
                />
              )}
              {guitar.latency && (
                <details>
                  <summary>Latency and audio device</summary>
                  <p>
                    Sample rate: {guitar.latency.sampleRate} Hz. Block:{' '}
                    {guitar.latency.quantumFrames} frames,{' '}
                    {(
                      (guitar.latency.quantumFrames /
                        guitar.latency.sampleRate) *
                      1000
                    ).toFixed(2)}{' '}
                    ms
                    {guitar.latency.quantumReported ? '' : ' (requested)'}.
                  </p>
                  <p>
                    Input: {latencyLabel(guitar.latency.inputMs)}. Output
                    buffer: {latencyLabel(guitar.latency.baseMs)}. Output
                    device: {latencyLabel(guitar.latency.outputMs)}.
                  </p>
                  <p>
                    These are browser measurements. Total latency from
                    microphone to headphones requires a separate measurement.
                    Use a wired connection for the lowest latency.
                  </p>
                </details>
              )}
              <p>
                Recording captures the input before effects. Choose when to
                recognize notes.
              </p>
              <label>
                Audio recognition
                <select
                  aria-label="Audio recognition mode"
                  value={guitar.recordingMode}
                  disabled={guitar.isRecording || guitar.processing}
                  onChange={event =>
                    guitar.setRecordingMode(event.target.value as RecordingMode)
                  }
                >
                  <option value="live">Notes and chords in real time</option>
                  <option value="live-mono">Single note: fast mode</option>
                  <option value="polyphonic">
                    Notes and chords after recording
                  </option>
                </select>
              </label>
              <p>
                {guitar.recordingMode === 'live'
                  ? 'Notes and chords appear on the staff and tablature during recording. Bends, slides, vibrato and wide vibrato are recognized in solo passages. Use a clean signal from one instrument. Uncertain overtones are discarded; quiet voices in dense chords may be missed. Live sound can stay on.'
                  : guitar.recordingMode === 'live-mono'
                  ? 'Play one note at a time. Bends, slides, vibrato and wide vibrato appear during recording. Fast monophonic mode suits short sounds and fast passages.'
                  : 'Notes and full chords are recognized after you stop recording and turn off live sound.'}
              </p>
              {guitar.isRecording && guitar.recordingMode !== 'polyphonic' && (
                <p role="status">
                  Notes are recorded in real time. Close Connections to see the
                  staff or tablature.
                </p>
              )}
              <LiveAudioRecognition />
              <Actions>
                <button
                  type="button"
                  disabled={guitar.processing && !guitar.isRecording}
                  onClick={guitar.toggleRecording}
                >
                  {guitar.isRecording
                    ? guitar.recordingMode !== 'polyphonic'
                      ? 'Stop audio recording'
                      : 'Stop and transcribe'
                    : 'Record audio'}
                </button>
                <button type="button" onClick={guitar.disconnect}>
                  Disconnect input
                </button>
              </Actions>
              <p>
                You can also use Record in the sandbox. If you monitor processed
                sound in Melody Generator, turn off Direct Monitor on your audio
                interface to avoid hearing a second, clean signal.
              </p>
            </>
          ) : (
            <Actions>
              <button
                type="button"
                disabled={guitar.connecting}
                onClick={() => guitar.connect()}
              >
                {guitar.connecting ? 'Connecting…' : 'Connect audio input'}
              </button>
              {guitar.connecting && (
                <button type="button" onClick={guitar.disconnect}>
                  Cancel
                </button>
              )}
            </Actions>
          )}
          {guitar.processing && (
            <div role="status">
              <p>
                {guitar.progress > 0
                  ? `Recognition: ${Math.round(guitar.progress * 100)}%`
                  : 'Loading recognition…'}
              </p>
              <progress
                max={1}
                value={guitar.progress || undefined}
                aria-label="Guitar recognition"
              />
            </div>
          )}
          {guitar.error && <p role="alert">{guitar.error}</p>}
          {guitar.notice && <p role="status">{guitar.notice}</p>}
          {guitar.hasTake && (
            <>
              {!guitar.connected && (
                <LiveInputEffects
                  settings={guitar.liveEffects}
                  onChange={guitar.updateLiveEffects}
                />
              )}
              <GuitarRecordingExport recording={guitar} />
              {guitar.error && guitar.canRetry && (
                <button
                  type="button"
                  disabled={guitar.processing}
                  onClick={guitar.retry}
                >
                  Retry recognition
                </button>
              )}
            </>
          )}
        </Panel>
      )}
    </Wrapper>
  );
};

const Wrapper = styled.div`
  display: contents;
  button,
  select {
    font-size: 12px;
  }
`;
const Mute = styled.button`
  order: 2;
  min-height: 42px;
  border-color: ${p => p.theme.primary};
  color: ${p => p.theme.primary};
`;
const EmergencyMute = styled(Mute)`
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 2000;
  background: ${p => p.theme.surface};
  border: 2px solid ${p => p.theme.primary};
  border-radius: 8px;
  padding: 10px 16px;
  box-shadow: 0 2px 12px ${p => p.theme.shadow};
`;

const latencyLabel = (value?: number) =>
  value === undefined ? 'no data' : `${value.toFixed(2)} ms`;
const Panel = styled.section`
  min-width: 0;
  font-size: 12px;
  p {
    margin: 12px 0;
    line-height: 1.5;
    color: ${p => p.theme.textSecondary};
  }
  label {
    display: flex;
    flex: 1;
    min-width: 0;
    flex-direction: column;
    gap: 6px;
  }
  select,
  progress,
  meter {
    width: 100%;
  }
`;
const Fields = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  label {
    min-width: min(210px, 100%);
  }
`;
const Actions = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
`;
const Level = styled.div`
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 12px;
  color: ${p => p.theme.textSecondary};
`;
