import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from 'react';
import { Link, useLocation } from 'react-router-dom';
import styled from 'styled-components';

import { useConnectedGuitarInput } from 'app/services/GuitarInputService/context';

import { BrandLogo } from 'app/components/BrandLogo';
import { DrumMachinePlaybackControl } from 'app/components/DrumMachinePlaybackControl';
import { InputDevices } from 'app/components/InputDevices';
import { InstrumentEffects } from 'app/components/InstrumentEffects';
import { Metronome } from 'app/components/Metronome';
import { ThemeSwitch } from 'app/components/Settings/ThemeSwitch';
import { TimbrePicker } from 'app/components/TimbrePicker';

import { Navigation } from './Routing';

export const SideSection = () => {
  const guitar = useConnectedGuitarInput();
  const { pathname } = useLocation();
  const [panel, setPanel] = useState<
    'timbres' | 'effects' | 'inputs' | 'metronome' | null
  >(null);
  const header = useRef<HTMLElement>(null);
  const setTimbresOpen = useCallback(
    (open: boolean) =>
      setPanel(current =>
        open ? 'timbres' : current === 'timbres' ? null : current,
      ),
    [],
  );
  const setEffectsOpen = useCallback(
    (open: boolean) =>
      setPanel(current =>
        open ? 'effects' : current === 'effects' ? null : current,
      ),
    [],
  );
  const setInputsOpen = useCallback(
    (open: boolean) =>
      setPanel(current =>
        open ? 'inputs' : current === 'inputs' ? null : current,
      ),
    [],
  );
  const setMetronomeOpen = useCallback(
    (open: boolean) =>
      setPanel(current =>
        open ? 'metronome' : current === 'metronome' ? null : current,
      ),
    [],
  );

  useLayoutEffect(() => {
    const root = document.documentElement;
    const previousHeight = root.style.getPropertyValue('--app-header-height');
    const measure = () => {
      root.style.setProperty(
        '--app-header-height',
        `${header.current?.getBoundingClientRect().height ?? 0}px`,
      );
    };
    measure();
    const observer =
      typeof ResizeObserver === 'undefined'
        ? null
        : new ResizeObserver(measure);
    if (header.current) observer?.observe(header.current);
    window.addEventListener('resize', measure);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', measure);
      root.style.setProperty('--app-header-height', previousHeight);
    };
  }, []);

  useEffect(() => {
    setPanel(null);
  }, [pathname]);

  return (
    <HeaderSpace>
      <Header ref={header} aria-label="Melody Generator toolbar">
        <Toolbar>
          <Brand to="/sandbox/staff" onClick={() => setPanel(null)}>
            <BrandLogo />
            <div>Melody Generator</div>
          </Brand>
          <NavigationGroup>
            <Navigation onNavigate={() => setPanel(null)} />
          </NavigationGroup>
          <ControlsGroup>
            <TimbrePicker
              open={panel === 'timbres'}
              onOpenChange={setTimbresOpen}
            />
            <InstrumentEffects
              guitar={guitar}
              open={panel === 'effects'}
              onOpenChange={setEffectsOpen}
            />
            <InputDevices
              guitar={guitar}
              open={panel === 'inputs'}
              onOpenChange={setInputsOpen}
            />
            <Metronome
              open={panel === 'metronome'}
              onOpenChange={setMetronomeOpen}
            />
            <DrumMachinePlaybackControl />
            <ThemeSwitch />
          </ControlsGroup>
        </Toolbar>
      </Header>
    </HeaderSpace>
  );
};

const HeaderSpace = styled.div`
  height: var(--app-header-height, 0px);
`;

const Header = styled.header`
  position: fixed;
  inset: 0 0 auto;
  z-index: 50;
  border-bottom: 1px solid ${p => p.theme.border};
  background: ${p => p.theme.surface};
`;

const Toolbar = styled.div`
  max-width: 1280px;
  margin: 0 auto;
  padding: 6px 32px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  grid-template-areas: 'brand navigation controls';
  align-items: center;
  gap: 12px 16px;
  box-sizing: border-box;

  @media (max-width: 1100px) {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      'brand controls'
      'navigation navigation';
  }

  @media (max-width: 780px) {
    padding: 4px 12px;
    gap: 8px;
  }

  @media (max-width: 520px) {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      'brand'
      'controls'
      'navigation';
    justify-items: center;
  }
`;

const ControlsGroup = styled.div`
  grid-area: controls;
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 4px;

  @media (max-width: 520px) {
    justify-self: center;
    justify-content: center;
    flex-wrap: wrap;
  }
`;

const NavigationGroup = styled.div`
  grid-area: navigation;
  justify-self: center;
`;

const Brand = styled(Link)`
  grid-area: brand;
  justify-self: start;
  display: flex;
  align-items: center;
  gap: 8px;
  color: ${p => p.theme.text};
  text-decoration: none;
  font-size: 26px;
  font-weight: 650;
  letter-spacing: -1px;
  line-height: 1.15;
  min-width: max-content;

  img {
    flex-shrink: 0;
    object-fit: contain;
    /* Align the key shapes with the wordmark; the drumstick extends above. */
    transform: translateY(-3px);
  }

  @media (max-width: 780px) {
    min-width: 0;
    font-size: 20px;
    gap: 6px;
    img {
      width: 30px;
      height: 30px;
    }
    div {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
  }
`;
