import { useEffect, useId, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import styled from 'styled-components';

import {
  CustomDrumSample,
  DRUM_SAMPLE_GROUPS,
  DrumSample,
  sampleKey,
} from 'app/services/DrumMachineService/samples';
import { useSampleRecording } from 'app/services/DrumMachineService/useSampleRecording';

import { drumSampleOptions, getDrumSamplePresentation } from './catalog';

interface Props {
  label: string;
  sample: DrumSample;
  customSamples: CustomDrumSample[];
  importing: boolean;
  microphone: ReturnType<typeof useSampleRecording>;
  error: string;
  onSelect: (sample: DrumSample) => Promise<void>;
  onImport: (file: File) => void;
  onRecord: () => void;
  onPreview: () => void;
  onClose: () => void;
}

export const DrumSamplePicker = ({
  label,
  sample,
  customSamples,
  importing,
  microphone,
  error,
  onSelect,
  onImport,
  onRecord,
  onPreview,
  onClose,
}: Props) => {
  const id = useId();
  const panel = useRef<HTMLDivElement>(null);
  const search = useRef<HTMLInputElement>(null);
  const [query, setQuery] = useState('');
  const [group, setGroup] = useState('All');
  const [pending, setPending] = useState('');
  const selection = useRef({ request: 0, mounted: true }).current;
  const dismiss = useRef(onClose);
  dismiss.current = onClose;
  const busy = importing || !!microphone.recording;
  const selected = getDrumSamplePresentation(sample);

  useEffect(() => {
    const previousFocus = document.activeElement;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    selection.mounted = true;
    search.current?.focus();
    const keyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        dismiss.current();
        return;
      }
      if (event.key !== 'Tab') return;
      const controls = Array.from(
        panel.current?.querySelectorAll<HTMLElement>(
          'button:not(:disabled), input:not(:disabled), [tabindex="0"]',
        ) ?? [],
      );
      const first = controls[0];
      const last = controls[controls.length - 1];
      if (
        !panel.current?.contains(document.activeElement) ||
        (event.shiftKey && document.activeElement === first)
      ) {
        event.preventDefault();
        (event.shiftKey ? last : first)?.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first?.focus();
      }
    };
    window.addEventListener('keydown', keyDown, true);
    return () => {
      window.removeEventListener('keydown', keyDown, true);
      selection.mounted = false;
      document.body.style.overflow = previousOverflow;
      if (previousFocus instanceof HTMLElement) previousFocus.focus();
    };
  }, [selection]);

  const savedSamples =
    sample.kind === 'custom' &&
    !customSamples.some(item => item.id === sample.id)
      ? [sample, ...customSamples]
      : customSamples;
  const options = [
    ...drumSampleOptions,
    ...savedSamples.map(sample => ({
      sample,
      label: sample.name,
      group: 'My Samples',
    })),
  ];
  const normalizedQuery = query.trim().toLocaleLowerCase('en');
  const visible = options.filter(
    option =>
      (group === 'All' || option.group === group) &&
      `${option.label} ${option.group}`
        .toLocaleLowerCase('en')
        .includes(normalizedQuery),
  );

  return createPortal(
    <Backdrop
      onClick={event => {
        if (event.target === event.currentTarget) onClose();
      }}
      onKeyDown={event => event.stopPropagation()}
    >
      <Dialog
        ref={panel}
        role="dialog"
        aria-modal="true"
        aria-labelledby={`${id}-title`}
        aria-describedby={`${id}-hint`}
      >
        <Header>
          <div>
            <Eyebrow>Track: {label}</Eyebrow>
            <h2 id={`${id}-title`}>Choose a sample</h2>
          </div>
          <Close
            type="button"
            aria-label="Close sample picker"
            onClick={onClose}
          >
            ×
          </Close>
        </Header>
        <Tools>
          <Search
            ref={search}
            type="search"
            aria-label="Search samples"
            placeholder="Search sounds or instruments"
            value={query}
            onChange={event => setQuery(event.target.value)}
          />
          <Actions>
            <Upload $disabled={busy}>
              Upload
              <input
                type="file"
                accept="audio/*,.wav,.mp3,.ogg,.m4a,.webm,.flac,.aac"
                aria-label={`Upload sample: ${label}`}
                disabled={busy}
                onChange={event => {
                  const file = event.target.files?.[0];
                  event.target.value = '';
                  if (file) onImport(file);
                }}
              />
            </Upload>
            <button
              type="button"
              aria-label={`Record sample: ${label}`}
              disabled={busy}
              onClick={onRecord}
            >
              Record
            </button>
          </Actions>
        </Tools>
        <Hint id={`${id}-hint`}>
          Choose a card or add your own sound. Audio files up to 10 MB and 10
          seconds.
        </Hint>
        {microphone.recording && (
          <Capture role="status">
            <span>
              {microphone.recording.ready
                ? 'Recording. Up to 10 seconds.'
                : 'Waiting for microphone access…'}
            </span>
            {microphone.recording.ready && (
              <button type="button" onClick={microphone.stop}>
                Save recording
              </button>
            )}
            <button type="button" onClick={microphone.cancel}>
              Cancel recording
            </button>
          </Capture>
        )}
        {importing && (
          <Status role="status">Preparing and saving sample…</Status>
        )}
        {(error || microphone.error) && (
          <ErrorMessage role="alert">{error || microphone.error}</ErrorMessage>
        )}
        <Filters role="group" aria-label="Sample instruments">
          {[
            'All',
            ...DRUM_SAMPLE_GROUPS.map(group => group.label),
            'My Samples',
          ].map(value => (
            <Filter
              key={value}
              type="button"
              aria-pressed={group === value}
              onClick={() => setGroup(value)}
            >
              {value}
            </Filter>
          ))}
        </Filters>
        <Results aria-live="polite">Found: {visible.length}</Results>
        <Library>
          {visible.length ? (
            <Cards aria-label="Samples">
              {visible.map(option => {
                const key = sampleKey(option.sample);
                const active = key === sampleKey(sample);
                const presentation = getDrumSamplePresentation(option.sample);
                return (
                  <li key={key}>
                    <Card
                      type="button"
                      aria-label={`Select sample: ${option.label}`}
                      aria-pressed={active}
                      aria-busy={pending === key}
                      disabled={busy}
                      onClick={async () => {
                        const request = ++selection.request;
                        setPending(key);
                        try {
                          await onSelect(option.sample);
                        } finally {
                          if (
                            selection.mounted &&
                            request === selection.request
                          )
                            setPending('');
                        }
                      }}
                    >
                      <Artwork src={presentation.image} alt="" loading="lazy" />
                      <CardLabel>{option.label}</CardLabel>
                      <CardHint>
                        {pending === key
                          ? 'Loading…'
                          : active
                          ? 'Selected'
                          : option.group}
                      </CardHint>
                    </Card>
                  </li>
                );
              })}
            </Cards>
          ) : (
            <Empty>
              <strong>
                {group === 'My Samples' && !query
                  ? 'Your sounds will appear here'
                  : 'No samples found'}
              </strong>
              <p>
                {group === 'My Samples' && !query
                  ? 'Upload an audio file or record a sound with your microphone.'
                  : 'Try another name or select all instruments.'}
              </p>
            </Empty>
          )}
        </Library>
        <Footer>
          <Current>
            <img src={selected.image} alt="" />
            <div>
              <small>Current sample</small>
              <strong>{selected.label}</strong>
            </div>
          </Current>
          <Actions>
            <button
              type="button"
              disabled={busy || !!pending}
              onClick={onPreview}
            >
              Preview
            </button>
            <Done type="button" onClick={onClose}>
              Done
            </Done>
          </Actions>
        </Footer>
      </Dialog>
    </Backdrop>,
    document.body,
  );
};

