import { getNoteDuration } from 'app/services/MelodiesService/timing';
import type { NoteInMelody } from 'app/services/MelodiesService/types';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { splitNote } from 'app/services/NotesService/noteUtils';
import type { Note } from 'app/services/NotesService/types';

import { STRINGS, StringInstrumentType } from './tuning';

export type FretPosition = { string: number; fret: number };
export type TablatureFingering = {
  positions: (FretPosition | undefined)[];
  hasUncomfortableChords: boolean;
};

const MAX_FRET = 24;
const PREFERRED_SPAN = 4;
const MAX_SPAN = 5;
const LOOKAHEAD_ATTACKS = 8;
const PHRASE_PAUSE_MS = 1000;
const pitch = (note: Note) => {
  const [name, octave] = splitNote(note);
  return octave * 12 + chromaticNotes.indexOf(name);
};

const candidatesFor = (note: Note, instrument: StringInstrumentType) =>
  STRINGS[instrument].flatMap((open, string) => {
    const fret = pitch(note) - pitch(open);
    return fret >= 0 && fret <= MAX_FRET ? [{ string, fret }] : [];
  });

export const formatTabPosition = (
  position: FretPosition | undefined,
  string: number,
) =>
  position?.string === string ? String(position.fret).padStart(3, '-') : '---';

type Shape = { positions: (FretPosition | undefined)[]; cost: number };

// Find a chord shape in one hand position. Simultaneous notes must use
// different strings; unreachable pitches retain their empty columns.
const shapeAt = (
  candidates: FretPosition[][],
  firstFret: number,
): Shape | undefined => {
  const choices = candidates.map(options =>
    options.filter(
      point => point.fret >= firstFret && point.fret <= firstFret + MAX_SPAN,
    ),
  );
  if (
    choices.some(
      (options, index) => !options.length && candidates[index].length,
    )
  )
    return undefined;
  const order = choices
    .map((options, index) => ({ options, index }))
    .filter(item => item.options.length)
    .sort((a, b) => a.options.length - b.options.length);
  const positions: (FretPosition | undefined)[] = Array(candidates.length);
  let best: Shape | undefined;
  const visit = (index: number, strings: number, cost: number) => {
    if (best && cost >= best.cost) return;
    if (index === order.length) {
      best = { positions: [...positions], cost };
      return;
    }
    const item = order[index];
    item.options.forEach(point => {
      if (strings & (1 << point.string)) return;
      positions[item.index] = point;
      visit(
        index + 1,
        strings | (1 << point.string),
        cost +
          point.fret * 0.005 +
          (point.fret > firstFret + PREFERRED_SPAN ? 0.5 : 0),
      );
    });
  };
  visit(0, 0, firstFret * 0.02);
  return best;
};

/** Keep each local passage in its chosen hand position until it no longer
 * fits. Look ahead a short riff, never refingering earlier passages to suit
 * distant notes. A second of silence starts a fresh phrase. Screen/PDF line
 * breaks do not affect the plan; lower positions and frets win ties.
 * The completed-score pass refines each established section using all of its
 * notes, without pulling separate riffs into a shared hand position.
 * No pitch, timing, source order or source object is changed.
 */
const getAutomaticFingering = (
  notes: readonly NoteInMelody[],
  instrument: StringInstrumentType,
  optimize = false,
  complete = false,
): TablatureFingering => {
  const candidates = notes.map(event => candidatesFor(event.note, instrument));
  const positions: (FretPosition | undefined)[] = candidates.map(
    options => options[0],
  );
  if (!optimize || !notes.length)
    return { positions, hasUncomfortableChords: false };

  const groups: { start: number; end: number; indices: number[] }[] = [];
  notes
    .map((event, index) => ({
      start: event.start,
      end: event.start + getNoteDuration(event),
      index,
    }))
    .sort((a, b) => a.start - b.start)
    .forEach(event => {
      const previous = groups[groups.length - 1];
      if (previous?.start === event.start) {
        previous.indices.push(event.index);
        previous.end = Math.max(previous.end, event.end);
      } else
        groups.push({
          start: event.start,
          end: event.end,
          indices: [event.index],
        });
    });

  let hasUncomfortableChords = false;
  let soundingUntil = -Infinity;
  const passages = groups.map(group => {
    const startsPhrase = group.start - soundingUntil >= PHRASE_PAUSE_MS;
    // Include all still-sounding voices when measuring silence between phrases.
    soundingUntil = Math.max(soundingUntil, group.end);
    const options = group.indices.map(index => candidates[index]);
    let shapes = Array.from({ length: MAX_FRET + 1 }, (_, firstFret) =>
      shapeAt(options, firstFret),
    );
    if (!shapes.some(Boolean)) {
      // Some imported chords cannot be played on this instrument. Keep every
      // pitch visible at its individual position and report the limitation.
      hasUncomfortableChords = true;
      shapes = Array.from({ length: MAX_FRET + 1 }, () => ({
        positions: options.map(points => points[0]),
        cost: 0,
      }));
    }
    return { ...group, startsPhrase, shapes };
  });

  let firstFret: number | undefined;
  const sections: typeof passages[] = [];
  passages.forEach((group, index) => {
    if (group.startsPhrase) firstFret = undefined;
    if (firstFret === undefined || !group.shapes[firstFret]) {
      sections.push([]);
      let best = { firstFret: 0, length: -1, cost: Infinity };
      group.shapes.forEach((shape, candidate) => {
        if (!shape) return;
        const distance =
          firstFret === undefined ? 0 : Math.abs(candidate - firstFret);
        let cost = distance ? 8 + distance * 2 : 0;
        let length = 0;
        for (
          let next = index;
          next < Math.min(passages.length, index + LOOKAHEAD_ATTACKS);
          next++
        ) {
          if (next > index && passages[next].startsPhrase) break;
          const nextShape = passages[next].shapes[candidate];
          if (!nextShape) break;
          cost += nextShape.cost;
          length++;
        }
        if (
          length > best.length ||
          (length === best.length && cost < best.cost)
        )
          best = { firstFret: candidate, length, cost };
      });
      firstFret = best.firstFret;
    }
    sections[sections.length - 1].push(group);
    const selected = group.shapes[firstFret]!;
    group.indices.forEach((noteIndex, offset) => {
      positions[noteIndex] = selected.positions[offset];
    });
  });

  if (complete) {
    let previousFret: number | undefined;
    sections.forEach(section => {
      if (section[0].startsPhrase) previousFret = undefined;
      let best = { firstFret: 0, stretch: Infinity, cost: Infinity };
      for (let candidate = 0; candidate <= MAX_FRET; candidate++) {
        const shapes = section.map(group => group.shapes[candidate]);
        if (shapes.some(shape => !shape)) continue;
        let lowest = Infinity;
        let highest = -Infinity;
        shapes.forEach(shape =>
          shape!.positions.forEach(point => {
            if (point) {
              lowest = Math.min(lowest, point.fret);
              highest = Math.max(highest, point.fret);
            }
          }),
        );
        const stretch = Math.max(0, highest - lowest - PREFERRED_SPAN);
        const distance =
          previousFret === undefined ? 0 : Math.abs(candidate - previousFret);
        const cost =
          shapes.reduce((sum, shape) => sum + shape!.cost, 0) +
          (distance ? 8 + distance * 2 : 0);
        if (
          stretch < best.stretch ||
          (stretch === best.stretch && cost < best.cost)
        )
          best = { firstFret: candidate, stretch, cost };
      }
      section.forEach(group => {
        const shape = group.shapes[best.firstFret]!;
        group.indices.forEach((index, offset) => {
          positions[index] = shape.positions[offset];
        });
      });
      previousFret = best.firstFret;
    });
  }
  return { positions, hasUncomfortableChords };
};

/** Manual choices win over automatic fingering only while they still match
 * the sounding pitch and the selected tuning. Stale or malformed saved
 * positions must never change the pitch displayed in a tab. */
export const getTablatureFingering = (
  notes: readonly NoteInMelody[],
  instrument: StringInstrumentType,
  optimize = false,
  complete = false,
): TablatureFingering => {
  const result = getAutomaticFingering(notes, instrument, optimize, complete);
  notes.forEach((event, index) => {
    const manual = event.tablature?.[instrument];
    const valid = candidatesFor(event.note, instrument).find(
      point => point.string === manual?.string && point.fret === manual?.fret,
    );
    if (valid) result.positions[index] = valid;
  });
  return result;
};

/** Move the entire selection by the same number of strings. All frets must
 * move in the requested direction and remain playable; partial moves are
 * never applied. Chords retain separate strings, including unselected notes
 * at the same attack. The original events and their timing stay intact. */
export const moveTablatureSelection = (
  notes: readonly NoteInMelody[],
  instrument: StringInstrumentType,
  indices: readonly number[],
  positions: readonly (FretPosition | undefined)[],
  direction: 'higher' | 'lower',
): NoteInMelody[] | undefined => {
  if (
    !indices.length ||
    indices.some(index => !notes[index] || !positions[index])
  )
    return undefined;
  const selected = new Set(indices);
  const stringCount = STRINGS[instrument].length;
  for (let distance = 1; distance < stringCount; distance++) {
    for (const offset of [distance, -distance]) {
      const moved = indices.map(index => {
        const previous = positions[index]!;
        return candidatesFor(notes[index].note, instrument).find(
          point =>
            point.string === previous.string + offset &&
            (direction === 'higher'
              ? point.fret > previous.fret
              : point.fret < previous.fret),
        );
      });
      if (moved.some(point => !point)) continue;
      const next = [...positions];
      indices.forEach((index, i) => (next[index] = moved[i]));
      const hasCollision = indices.some(index =>
        notes.some(
          (event, other) =>
            other !== index &&
            event.start === notes[index].start &&
            next[other]?.string === next[index]!.string,
        ),
      );
      if (hasCollision) continue;
      return notes.map((event, index) =>
        selected.has(index)
          ? {
              ...event,
              tablature: { ...event.tablature, [instrument]: next[index] },
            }
          : event,
      );
    }
  }
  return undefined;
};
